mapper.select:
        select
        *
        from
        wms_plant_convert
        where
        bool_delete_enum = 0
        
            and  basic_class = #{basicClass}
        
        
            and receipt_serial_number = #{receiptSerialNumber}
        

        
            and reviewer_name like CONCAT('%', #{operatorName},'%')
        
        
            and find_in_set(#{projectId},project_ids)
        
        
            and find_in_set(#{taskOrderNumber},task_order_number)
        
        
            
                and create_time > #{createTime[0]}
            
            
                and create_time < #{createTime[1]}
